        else{$response=call_user_func($this->request,'https://analyticsdata.googleapis.com/v1beta/properties/'.$g['property'].':runReport',['dateRanges'=>[['startDate'=>$from,'endDate'=>$to]],'dimensions'=>[['name'=>'date'],['name'=>'pagePath']],'metrics'=>[['name'=>'sessions'],['name'=>'activeUsers'],['name'=>'keyEvents'],['name'=>'totalRevenue']],'offset'=>(string)$offset,'limit'=>'1000','orderBys'=>[['dimension'=>['dimensionName'=>'date']],['dimension'=>['dimensionName'=>'pagePath']]]],$headers);foreach($response['rows']??[] as $r){$date=$r['dimensionValues'][0]['value'];$page=$r['dimensionValues'][1]['value'];$rows[]=['id'=>hash('sha256',$date.'|'.$page),'date'=>substr($date,0,4).'-'.substr($date,4,2).'-'.substr($date,6,2),'page'=>$page,'sessions'=>$r['metricValues'][0]['value'],'active_users'=>$r['metricValues'][1]['value'],'conversions'=>$r['metricValues'][2]['value'],'revenue'=>$r['metricValues'][3]['value'],'currency'=>$response['metadata']['currencyCode']??''];}$more=$offset+count($rows)<(int)($response['rowCount']??0);}
